export const HEIGHTS = ["1", "3", "5", "7.5", "10"];

export const heightLabel = (h) => (h === "1" || h === "3" ? `${h}m springboard` : `${h}m platform`);

// DD for a dive (e.g. "107B") at a height ("3", "10"), or null if unknown.
export function lookupDD(code, height) {
  const row = DD_TABLE[String(code ?? "").trim().toUpperCase()];
  const dd = row && row[String(height)];
  return typeof dd === "number" ? dd : null;
}

// Every dive that has a DD at the given height, for pickers.
export function divesAtHeight(height) {
  return Object.keys(DD_TABLE).filter((k) => DD_TABLE[k][String(height)] !== undefined);
}
